  options.exposeHeadRoutes = initialConfig.exposeHeadRoutes

  // we need to set this before calling createServer
  options.http2SessionTimeout = initialConfig.http2SessionTimeout

  return {
    options,
    genReqId,
    logController,
    hasLogger,
    initialConfig
  }
}

