      payload.removeListener('error', onEnd)
      done(new FST_ERR_CTP_BODY_TOO_LARGE(), undefined)
      return
    }

    chunks.push(chunk)
  }

  function onEnd (err) {
    payload.removeListener('data', onData)
    payload.removeListener('end', onEnd)
    payload.removeListener('error', onEnd)

    if (err != null) {
      if (!(typeof err.statusCode === 'number' && err.statusCode >= 400)) {
        err.statusCode = 400
      }
      done(err, undefined)
      return
    }

    if (!Number.isNaN(contentLength) && (payload.receivedEncodedLength || receivedLength) !== contentLength) {
      done(new FST_ERR_CTP_INVALID_CONTENT_LENGTH(), undefined)
      return
    }

    let body
    if (asString) {
      // Decoding the whole body at once also keeps multi-byte characters
      // split across chunks intact
      body = chunks.length === 1
        ? chunks[0].toString('utf8')
        : Buffer.concat(chunks, receivedLength).toString('utf8')
    } else {
      // Always copy so the parser never receives a view over the shared
      // socket read buffer
      body = Buffer.concat(chunks, receivedLength)
    }

    let result
    try {
      result = parser.fn(request, body, done)
    } catch (error) {
      done(error, undefined)
      return
    }
    if (result && typeof result.then === 'function') {
      result.then(body => { done(null, body) }, done)
    }
  }
}

