    })

    await fastify.listen({ port: 0 })
    t.after(() => fastify.close())

    const res = await getWithTrailers(getServerUrl(fastify))
    t.assert.strictEqual(res.statusCode, 200)
    t.assert.deepStrictEqual(res.trailers, {})
